import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        t_str = next(iterator)
        T = int(t_str)
    except StopIteration:
        return

    for _ in range(T):
        teams = {}

        for _ in range(12):
            home_name = next(iterator)
            home_goals_str = next(iterator)
            vs_marker = next(iterator) # "vs."
            away_goals_str = next(iterator)
            away_name = next(iterator)

            home_goals = int(home_goals_str)
            away_goals = int(away_goals_str)

            if home_name not in teams:
                teams[home_name] = {'points': 0, 'gd': 0}
            if away_name not in teams:
                teams[away_name] = {'points': 0, 'gd': 0}

            teams[home_name]['gd'] += (home_goals - away_goals)
            teams[away_name]['gd'] += (away_goals - home_goals)

            if home_goals > away_goals:
                teams[home_name]['points'] += 3
            elif away_goals > home_goals:
                teams[away_name]['points'] += 3
            else:
                teams[home_name]['points'] += 1
                teams[away_name]['points'] += 1

        team_list = []
        for name, stats in teams.items():
            team_list.append((name, stats['points'], stats['gd']))

        # Sort by points descending, then by goal difference descending
        team_list.sort(key=lambda x: (-x[1], -x[2]))

        print(f"{team_list[0][0]} {team_list[1][0]}")

if __name__ == "__main__":
    solve()
